"""PWA shell assets: service worker, HTML, fixed icon fallbacks."""
import hashlib
ICON_192_B64 = ""
ICON_512_B64 = ""

SW_JS_TEMPLATE = """
// CACHE_NAME is filled in automatically below (from a hash of this file +
// PWA_HTML) rather than a manually-bumped version string. The old approach
// (hand-incrementing "v8" on every deploy) was easy to forget, and
// forgetting it meant an installed PWA could stay stuck on stale cached
// HTML that had drifted out of sync with what a plain browser tab (which
// just hits the network) shows. Deriving it from content means the cache
// name only ever changes when the shell actually changed - automatic, and
// never stale.
const CACHE_NAME = "ds-dashboard-__CACHE_VERSION__";
const SHELL = ["/dashboard", "/manifest.json", "/icon-192.png", "/icon-512.png"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(SHELL)));
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))))
  );
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);

  if (url.pathname === "/status") {
    event.respondWith(
      fetch(event.request).catch(
        () => new Response(JSON.stringify({ total: 0, online: 0, offline: 0, accounts: [] }), {
          headers: { "Content-Type": "application/json" },
        })
      )
    );
    return;
  }

  // Network-first for the app shell (HTML/manifest/icons) so the installed
  // PWA always shows what's currently deployed - same as a fresh browser
  // tab would - and only falls back to the cached copy when offline.
  if (SHELL.includes(url.pathname)) {
    event.respondWith(
      fetch(event.request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(event.request, copy));
          return response;
        })
        .catch(() => caches.match(event.request))
    );
    return;
  }

  event.respondWith(caches.match(event.request).then((cached) => cached || fetch(event.request)));
});
"""

